using System.Security.Cryptography;using System.Text;using System.Text.Json;using CommanderOwnerConsent;
namespace CommanderOwnerAcceptance;
internal static class ProbeQA
{
 internal static int Run()
 {
  var pass=0;var failed=new List<string>();void Test(string name,Action f){try{f();pass++;}catch{failed.Add(name);}}void Reject(string name,Action f){Test(name,()=>{try{f();}catch(ConsentFault){return;}catch(JsonException){return;}catch(CryptographicException){return;}throw new Exception("Expected reject");});}
  using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);using var wrong=ECDsa.Create(ECCurve.NamedCurves.nistP256);var now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();var assertion=ProbeCrypto.Assertion(key,now);
  Test("fixed_assertion",()=>ProbeCrypto.VerifyAssertion(assertion,key,now));Reject("wrong_assertion_key",()=>ProbeCrypto.VerifyAssertion(assertion,wrong,now));Reject("expired_assertion",()=>ProbeCrypto.VerifyAssertion(assertion,key,now+61000));Reject("future_assertion",()=>ProbeCrypto.VerifyAssertion(assertion,key,now-61000));Reject("malformed_assertion",()=>ProbeCrypto.VerifyAssertion("abc.def.ghi",key,now));
  string Sign(string typ,string kid,byte[] claims){var header=ProbeCrypto.Json(w=>{w.WriteString("alg","ES256");w.WriteString("kid",kid);w.WriteString("typ",typ);});var prefix=ConsentCore.B64(header)+"."+ConsentCore.B64(claims);return prefix+"."+ConsentCore.B64(key.SignData(Encoding.UTF8.GetBytes(prefix),HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation));}
  const string epoch="epoch:test",grant="grant:0123456789abcdef0123456789abcdef";
  byte[] Claims(string root="no-project",string scope="selftest",string resource=ProbeAuthority.Resource,long extra=300)=>ProbeCrypto.Json(w=>{w.WriteString("iss",ProbeAuthority.Issuer);w.WriteString("aud",resource);w.WriteString("sub","local-owner");w.WriteString("client_id",ProbeAuthority.Client);w.WriteString("grant_id",grant);w.WriteString("enrollment_epoch",epoch);w.WriteString("profile_id","selftest");w.WriteString("root_policy_id",root);w.WritePropertyName("actions");w.WriteStartArray();w.WriteStringValue("selftest");w.WriteEndArray();w.WriteString("scope",scope);w.WriteNumber("iat",now/1000);w.WriteNumber("nbf",now/1000);w.WriteNumber("exp",now/1000+extra);w.WriteString("jti","token:0123456789abcdef0123456789abcdef");});
  var token=Sign("at+jwt","owner-selftest-es256",Claims());Test("no_project_token",()=>ProbeCrypto.VerifyToken(token,key,epoch,grant,now));Reject("wrong_token_key",()=>ProbeCrypto.VerifyToken(token,wrong,epoch,grant,now));Reject("wrong_epoch",()=>ProbeCrypto.VerifyToken(token,key,"epoch:other",grant,now));Reject("wrong_grant",()=>ProbeCrypto.VerifyToken(token,key,epoch,"grant:other",now));Reject("expired_token",()=>ProbeCrypto.VerifyToken(token,key,epoch,grant,now+301000));Reject("project_scope",()=>ProbeCrypto.VerifyToken(Sign("at+jwt","owner-selftest-es256",Claims(scope:"filesystem.write")),key,epoch,grant,now));Reject("project_root",()=>ProbeCrypto.VerifyToken(Sign("at+jwt","owner-selftest-es256",Claims(root:"real-project")),key,epoch,grant,now));Reject("foreign_resource",()=>ProbeCrypto.VerifyToken(Sign("at+jwt","owner-selftest-es256",Claims(resource:"https://other.invalid")),key,epoch,grant,now));Reject("excess_token_lifetime",()=>ProbeCrypto.VerifyToken(Sign("at+jwt","owner-selftest-es256",Claims(extra:301)),key,epoch,grant,now));Reject("wrong_token_header",()=>ProbeCrypto.VerifyToken(Sign("JWT","owner-selftest-es256",Claims()),key,epoch,grant,now));
  byte[] State(long seq=2,string status="active",string root="no-project",long issuedDelta=0)=>ProbeCrypto.Json(w=>{w.WriteString("kind","rc-grant-state-v1");w.WriteString("issuer",ProbeAuthority.Issuer);w.WriteString("resource",ProbeAuthority.Resource);w.WriteString("ownerId","local-owner");w.WriteString("enrollmentEpoch",epoch);w.WriteString("grantId",grant);w.WriteString("status",status);w.WriteString("profileId","selftest");w.WriteString("rootPolicyId",root);foreach(var set in new[]{"actions","scopes"}){w.WritePropertyName(set);w.WriteStartArray();w.WriteStringValue("selftest");w.WriteEndArray();}w.WriteNumber("sequence",seq);w.WriteNumber("issuedAtMs",now+issuedDelta);w.WriteNumber("expiresAtMs",now+issuedDelta+15000);});
  byte[] Envelope(byte[] statement)=>ProbeCrypto.Json(w=>{w.WritePropertyName("statement");w.WriteRawValue(statement);w.WriteString("signature",ConsentCore.B64(key.SignData(Encoding.UTF8.GetBytes("RC_OWNER_OAUTH_GRANT_STATE_V1\n").Concat(statement).ToArray(),HashAlgorithmName.SHA256,DSASignatureFormat.Rfc3279DerSequence)));});
  void Verify(byte[] env,ECDsa k,long minimum=1,long? time=null){using var d=ConsentCore.Strict(env);ProbeCrypto.VerifyState(d.RootElement,k,epoch,grant,time??now,minimum);}
  var state=Envelope(State());Test("fresh_active_state",()=>Verify(state,key));Reject("wrong_state_key",()=>Verify(state,wrong));Reject("state_sequence_replay",()=>Verify(state,key,2));Reject("expired_state",()=>Verify(state,key,time:now+15001));Reject("future_state",()=>Verify(Envelope(State(issuedDelta:1000)),key));Reject("revoked_state",()=>Verify(Envelope(State(status:"revoked")),key));Reject("project_state_root",()=>Verify(Envelope(State(root:"project")),key));Reject("duplicate_json",()=>ConsentCore.Strict(Encoding.UTF8.GetBytes("{\"x\":1,\"x\":2}")));
  var report=ProbeCrypto.Json(w=>{w.WriteString("schema","RC_OWNER_ACCEPTANCE_PURE_QA_V1");w.WriteNumber("pass",pass);w.WriteNumber("fail",failed.Count);w.WritePropertyName("failedCases");w.WriteStartArray();foreach(var f in failed)w.WriteStringValue(f);w.WriteEndArray();w.WriteBoolean("syntheticKeysInMemoryOnly",true);w.WriteBoolean("realPrivateKeyOpened",false);w.WriteBoolean("actualProxyOrConsentStarted",false);w.WriteBoolean("runtimeGDirectoryCreated",false);w.WriteBoolean("actualOwnerAcceptanceProven",false);});var text=Encoding.UTF8.GetString(report);ConsentCore.Need(!text.Contains(assertion,StringComparison.Ordinal)&&!text.Contains(token,StringComparison.Ordinal),"QA_PRIVACY");Console.WriteLine(text);return failed.Count==0?0:1;
 }
}
